using FamilyVeda.Application.Portal;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace FamilyVeda.Api.Controllers;

[Route("api/v1")]
[Authorize]
public sealed class AppointmentsController(IAppointmentService appointmentService) : ApiControllerBase
{
    [HttpPost("appointments")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<AppointmentDto>> Book(CreateAppointmentRequest request, CancellationToken cancellationToken)
    {
        var result = await appointmentService.BookAsync(request, cancellationToken);
        return Created($"/api/v1/appointments/{result.Id}", result);
    }

    [HttpGet("appointments/mine")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<IReadOnlyList<AppointmentDto>>> GetMine(CancellationToken cancellationToken) =>
        Ok(await appointmentService.GetMineAsync(cancellationToken));

    [HttpPost("appointments/{id:guid}/cancel")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<AppointmentDto>> Cancel(Guid id, CancellationToken cancellationToken) =>
        Ok(await appointmentService.CancelAsync(id, cancellationToken));

    [HttpGet("doctors/me/appointments")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<IReadOnlyList<AppointmentDto>>> GetForDoctor(DateTimeOffset? from, DateTimeOffset? to, CancellationToken cancellationToken) =>
        Ok(await appointmentService.GetForDoctorAsync(from, to, cancellationToken));

    [HttpPost("doctors/me/appointments/{id:guid}/confirm")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<AppointmentDto>> Confirm(Guid id, AppointmentActionRequest? request, CancellationToken cancellationToken) =>
        Ok(await appointmentService.ConfirmAsync(id, request ?? new AppointmentActionRequest(null), cancellationToken));

    [HttpPost("doctors/me/appointments/{id:guid}/complete")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<AppointmentDto>> Complete(Guid id, AppointmentActionRequest? request, CancellationToken cancellationToken) =>
        Ok(await appointmentService.CompleteAsync(id, request ?? new AppointmentActionRequest(null), cancellationToken));

    [HttpPost("doctors/me/appointments/{id:guid}/no-show")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<AppointmentDto>> NoShow(Guid id, AppointmentActionRequest? request, CancellationToken cancellationToken) =>
        Ok(await appointmentService.NoShowAsync(id, request ?? new AppointmentActionRequest(null), cancellationToken));

    [HttpPost("doctors/me/appointments/{id:guid}/cancel")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<AppointmentDto>> DoctorCancel(Guid id, AppointmentActionRequest? request, CancellationToken cancellationToken) =>
        Ok(await appointmentService.DoctorCancelAsync(id, request ?? new AppointmentActionRequest(null), cancellationToken));

    [HttpPost("doctors/me/appointments/{id:guid}/reschedule")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<AppointmentDto>> Reschedule(Guid id, RescheduleAppointmentRequest request, CancellationToken cancellationToken) =>
        Ok(await appointmentService.RescheduleAsync(id, request, cancellationToken));
}
